#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using Tools;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.blaze)]
    public class Blaze : AIEntityBehaviour
    {
        public Blaze(string nsp, string name) : base(nsp, name)
        {
            detector = new DispenserDetector()
            {
                ignoreHighEnemy = true,
                colliderFilter = (p, c) => ColliderFilter(p.entity, c)
            };
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetStateTimer(entity, new FrameTimer(SHOOT_COOLDOWN));
            var buff = entity.AddBuff<FlyBuff>();
            buff.SetProperty(FlyBuff.PROP_TARGET_HEIGHT, 1f);
        }
        protected override void UpdateAI(Entity enemy)
        {
            base.UpdateAI(enemy);
            if (CanShoot(enemy))
            {
                if (enemy.Target != null && !ValidateTarget(enemy, enemy.Target))
                {
                    enemy.Target = null;
                }
                enemy.Target = FindTarget(enemy);
            }
            else
            {
                enemy.Target = null;
            }

            switch (enemy.State)
            {
                case STATE_RANGED_ATTACK:
                    ShootFireBall(enemy);
                    break;
                default:
                    UnleaseBow(enemy);
                    break;
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetAnimationBool("Shooting", entity.State == STATE_RANGED_ATTACK);
        }
        private bool CanShoot(Entity enemy)
        {
            return enemy.Position.x <= enemy.Level.GetEntityColumnX(enemy.Level.GetMaxColumnCount() - 1);
        }
        private Entity? FindTarget(Entity entity)
        {
            return detector.DetectEntityWithTheLeast(entity, e => (e.GetCenter() - entity.Position).sqrMagnitude);
        }
        private bool ValidateTarget(Entity entity, Entity target)
        {
            return detector.ValidateTarget(entity, target);
        }
        private void ShootFireBall(Entity entity)
        {
            var shootTimer = GetStateTimer(entity);
            if (shootTimer != null)
            {
                shootTimer.Run(entity.GetAttackSpeed());
                if (shootTimer.Expired)
                {
                    if (!IsFiring(entity))
                    {
                        shootTimer.ResetTime(SHOOT_DURATION);
                        SetFiring(entity, true);
                    }
                    else
                    {
                        shootTimer.ResetTime(SHOOT_COOLDOWN);
                        SetFiring(entity, false);
                    }
                }
                if (IsFiring(entity))
                {
                    if (shootTimer.PassedInterval(10))
                    {
                        var target = FindTarget(entity);
                        if (target.ExistsAndAlive())
                        {
                            Fire(entity, target);
                        }
                    }
                }
            }
        }
        private void UnleaseBow(Entity enemy)
        {
            var shootTimer = GetStateTimer(enemy);
            shootTimer?.ResetTime(SHOOT_COOLDOWN);
            SetFiring(enemy, false);
        }
        private void Fire(Entity self, Entity target)
        {
            var param = self.GetShootParams();
            var shootPoint = self.GetShootPoint();
            var velocity = self.GetShotVelocity();
            var speed = velocity.magnitude;
            var direciton = (target.GetCenter() - shootPoint).normalized;
            param.velocity = speed * direciton;

            self.ShootProjectile(param);
            self.PlaySound(VanillaSoundID.fireCharge);
        }
        private bool ColliderFilter(Entity self, IEntityCollider collider)
        {
            var target = collider.Entity;
            if (target.IsFloor())
                return false;
            return true;
        }
        public static FrameTimer? GetStateTimer(Entity enemy) => enemy.GetProperty<FrameTimer>(PROP_STATE_TIMER);
        public static void SetStateTimer(Entity enemy, FrameTimer value) => enemy.SetProperty(PROP_STATE_TIMER, value);
        public static bool IsFiring(Entity enemy) => enemy.GetProperty<bool>(PROP_FIRING);
        public static void SetFiring(Entity enemy, bool value) => enemy.SetProperty(PROP_FIRING, value);
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("StateTimer");
        public static readonly VanillaEntityPropertyMeta<bool> PROP_FIRING = new VanillaEntityPropertyMeta<bool>("firing");
        private Detector detector;
        public const int STATE_WALK = LogicEnemyStates.WALK;
        public const int STATE_RANGED_ATTACK = LogicEnemyStates.RANGED_ATTACK;
        public const int SHOOT_COOLDOWN = 180;
        public const int SHOOT_DURATION = 35;
    }
}
